using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class ItaloSvevo
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Ad una data età nessuno di noi è quello a cui madre natura lo destinava; ci si ritrova con un carattere curvo come la pianta che avrebbe voluto seguire la direzione che segnalava la radice, ma che deviò per farsi strada attraverso pietre che le chiudevano il passaggio.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "In fondo il rimorso non è altro che il risultato di un dato modo di guardarsi in uno specchio.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Io quando guardo una montagna aspetto sempre che si converta in vulcano.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "La mutilazione per cui la vita perdette quello che non ebbe mai, il futuro, rende la vita più semplice, ma anche tanto priva di senso.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Le cose che si muovono potrebbero muoversi eternamente. Perché no? Non è questa la legge in cielo dove è certo vige la stessa legge che in terra? Ma io so che dalla nascita in poi anche la malattia è prevista e preparata. Da bel principio qualche organo è più debole e lavora con qualche sforzo e costringe a qualche sforzo qualche organo fraterno e dove c'è lo sforzo s'ingenera la fatica e perciò, infine, viene la morte.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Le donne sono sempre povere di parole precise.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "tutti i socialisti finiscono in pratica col ricorrere al mestiere del carnefice.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "La catena e la museruola sono solo per Argo. La museruola è un pezzo di preda che non è né coperta né sincera. Io non so che cosa sia. Certo è una muraglia posta fra me e il creato, una nebbia che copre e rende meno distinta la vita.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Fra il cane e l'uomo c'è un'altra grande differenza. L'uomo cambia d'umore ad ogni istante come una lepre furba di direzione. Invece ce ne vuol altro per far cambiare d'umore al cane. Talvolta Argo è lieto e vuol bene a tutti. Taglia l'aria con la coda perché in lui manca ogni sospetto e sa che non c'è nessuno che voglia pigliarlo per quella parte inerme. Poi è assalito da un dubbio: Forse qualcuno non gli vuol bene. Ma il dubbio è domato dalla sua coda che grida al vento: \"Tutto va bene e sono tutti amici\". È difficile frenarla se non si presenta l'evidente necessità di celarla fra le gambe. Ma l'uomo è un animale disgraziato perché non ha la coda.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Quando lo spinsi a filosofare (certo è Argo il primo filosofo di sua gente) ebbi da lui questa frase futurista: Odori tre uguale vita. Per giorni interi insistetti per averne il commento e non ebbi mai la ripetizione. La bestia è perfetta e non perfettibile. Chi la studia deve saper progredire. Notai la frase come stava e procedetti oltre. Avute poscia altre sue comunicazioni me ne derivò qualche luce e pensai di aver capito. Divide la natura in tre classi solo perché lui il massimo matematico è di tre; poi ne cita cinque e dalle sue esemplificazioni risulterebbe che ve ne sono molte di più. Io credo che questa è la vera, la grande sincerità filosofica.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "La grande differenza che c'è fra l'uomo e il cane è che il primo non sa il piacere delle busse che cessano.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Le cose hanno talvolta l'odore delle bestie che vi passarono su, specialmente se qualche cosa vi lasciarono, ma altrimenti le cose sono mute.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Le donne son fatte così. Ogni giorno che sorge porta loro una nuova interpretazione del passato. Dev'essere una vita poco monotona la loro.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "L'uomo è un animale molto più semplice del cane perché sente di più e più facilmente. Quando incontra un altro uomo gli tocca la mano e sembrerebbe quasi di non curarsi di quanto sta dietro di questa mano.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Oggidì era acquisito dalla scienza che le giovani e belle donne erano più necessarie ai vecchi che ai giovani. Naturalmente, oltre che la sorpassata legge morale, perché a questa necessità sia corrisposto, c'era l'ostacolo che anche alle giovani e belle donne era concessa la libertà di disporre di sé. Forse contro ogni giustizia, perché per la loro giovinezza e per la loro bellezza esse alla libertà non sono preparate. Oggetti troppo preziosi, venivano distribuiti anche più ingiustamente dell'oro stesso. Si conquistavano anche con un paio di mustacchi bene impomatati. Ai vecchi non si concedevano che in casi rarissimi: Gerontomania.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Aveva osservato che quando due italiani si trovano allo stesso tavolo, avevano la gran voglia di lasciarlo per non sentire più l'altro.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "In sogno una parola e il suo suono dipinge intera la persona che la emette.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Ero prossimo al sonno, ma avevo gli occhi tuttavia pieni di sole e tardavo a perdere i sensi. La dolcezza che in quell'età s'accompagna al riposo dopo una grande stanchezza, m'è evidente come un'immagine a sé, tanto evidente come se fossi adesso là accanto a quel caro corpo che più non esiste.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Le mie giornate finirono coll'essere piene di sigarette e di propositi di non fumare più e, per dire subito tutto, di tempo in tempo sono ancora tali. La ridda delle ultime sigarette, formatasi a vent'anni, si muove tuttavia. Meno violento è il proposito e la mia debolezza trova nel mio vecchio animo maggior indulgenza. Da vecchi si sorride della vita e di ogni suo contenuto. Posso anzi dire, che da qualche tempo io fumo molte sigarette.... che non sono le ultime.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Adesso che son qui, ad analizzarmi, sono colto da un dubbio: che io forse abbia amato tanto la sigaretta per poter riversare su di essa la colpa della mia incapacità? Chissà se cessando di fumare io sarei divenuto l'uomo ideale e forte che m'aspettavo? Forse fu tale dubbio che mi legò al mio vizio perché è un modo comodo di vivere quello di credersi grande di una grandezza latente.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Penso che la sigaretta abbia un gusto più intenso quand'è l'ultima. Anche le altre hanno un loro gusto speciale, ma meno intenso. L'ultima acquista il suo sapore dal sentimento della vittoria su sé stesso e la speranza di un prossimo futuro di forza e di salute. Le altre hanno la loro importanza perché accendendole si protesta la propria libertà e il futuro di forza e di salute permane, ma va un po' più lontano.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Eppoi il tempo, per me, non è quella cosa impensabile che non s'arresta mai. Da me, solo da me, ritorna.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "La malattia, è una convinzione ed io nacqui con quella convinzione.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "L'amore sano è quello che abbraccia una donna sola e intera, compreso il suo carattere e la sua intelligenza.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Ma fumai subito l'ultima sigaretta; e non era la mezzanotte, ma le ventitré, un'ora impossibile per un'ultima sigaretta.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Adesso che invecchio e m'avvicino al tipo del patriarca, anch'io sento che un'immoralità predicata è più punibile di un'azione immorale. Si arriva all'assassinio per amore o per odio; alla propaganda dell'assassinio solo per malvagità.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Insomma io, accanto a lui, rappresentavo la forza e talvolta penso che la scomparsa di quella debolezza, che mi elevava, fu sentita da me come una diminuzione.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Il pianto offusca le proprie colpe e permette di accusare, senz'obbiezioni, il destino. Piangevo perché perdevo il padre per cui ero sempre vissuto. Non importava che gli avessi tenuto poca compagnia. I miei sforzi per diventare migliore non erano stati fatti per dare una soddisfazione a lui?", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Quando si muore si ha ben altro da fare che di pensare alla morte.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "È proprio la religione vera quella che non occorre professare ad alta voce per averne il conforto di cui qualche volta — raramente — non si può fare a meno.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Non v'è niente di più difficile a questo mondo che di fare un matrimonio come si vuole.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "È libertà completa quella di poter fare ciò che si vuole a patto di fare anche qualche cosa che piaccia meno. La vera schiavitù è la condanna all'astensione: Tantalo e non Ercole.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Chissà se l'amo? È un dubbio che m'accompagnò per tutta la vita e oggidì posso pensare che l'amore accompagnato da tanto dubbio sia il vero amore.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Ma uccidere e sia pure a tradimento, è cosa più virile che danneggiare un amico riferendo una sua confidenza.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Compresi finalmente che cosa fosse la perfetta salute umana quando indovinai che il presente per lei era una verità tangibile in cui si poteva segregarsi e starci caldi. Cercai di esservi ammesso, e tentai di soggiornarvi risoluto di non deridere me e lei, perché questo conato non poteva essere altro che la mia malattia ed io dovevo almeno guardarmi dall'infettare chi a me s'era confidato. Anche perciò, nello sforzo di proteggere lei, seppi per qualche tempo movermi come un uomo sano.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "La salute non analizza se stessa e neppur si guarda nello specchio. Solo noi malati sappiamo qualche cosa di noi stessi.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "La religione di cui Augusta abbisognava non esigeva del tempo per acquisirsi o per praticarsi. Un inchino e l'immediato ritorno alla vita! Nulla di più. Da me la religione acquistava tutt'altro aspetto. Se avessi avuto la fede vera, io a questo mondo non avrei avuto che quella.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Il Copler, però, non faceva bene ad analizzarmi. Spiegare a qualcuno come è fatto, è un modo per autorizzarlo ad agire come desidera.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Io credo che l'accordo in un giudizio critico unisca intimamente.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Le lacrime non sono espresse dal dolore, ma dalla sua storia.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Ma del senno di poi si può sempre ridere e anche di quello di prima, perché non serve.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Perciò io penso che il rimorso non nasca dal rimpianto di una mala azione già commessa, ma dalla visione della propria colpevole disposizione. La parte superiore del corpo si china a guardare e giudicare l'altra parte e la trova deforme. Ne sente ribrezzo e questo si chiama rimorso. Anche nella tragedia antica la vittima non ritornava in vita e tuttavia il rimorso passava. Ciò significava che la deformità era guarita e che oramai il pianto altrui non aveva alcuna importanza. Dove poteva esserci posto per il rimorso in me che con tanta gioia e tanto affetto correvo dalla mia legittima moglie? Da molto tempo non m'ero sentito tanto puro.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "È perciò che solo allora cessò quel mio stato ch'io m'ostino a qualificare d'innocenza. Non era più possibile adorare Carla per un breve periodo della giornata eppoi odiarla per ventiquattr'ore continue, e levarsi ogni mattina ignorante come un neonato e rivivere la giornata, tanta simile alle precedenti, per sorprendersi delle avventure ch'essa apportava e che avrei dovuto sapere a mente. Ciò non era più possibile. Mi si prospettava l'eventualità di perdere per sempre la mia amante se non avessi saputo domare il mio desiderio di liberarmene. Io subito lo domai!", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Il mentitore dovrebbe tener presente che per essere creduto non bisogna dire che le menzogne necessarie.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Uno dei primi effetti della bellezza femminile su di un uomo è quello di levargli l'avarizia.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Quaggiù quando non ci vogliamo male ci amiamo tutti, ma però i nostri vivi desideri accompagnano solo gli affari cui partecipiamo.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Curioso come a questo mondo vi sia poca gente che si rassegni a perdite piccole; sono le grandi che inducono immediatamente alla grande rassegnazione.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Le avventure più gradevoli possono capitare quando meno ci si pensa [...]", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Grande, importante malattia quella di Basedow! Per me fu importantissimo di averla conosciuta. La studiai in varie monografie e credetti di scoprire appena allora il segreto essenziale del nostro organismo. Io credo che da molti come da me vi sieno dei periodi di tempo in cui certe idee occupino e ingombrino tutto il cervello chiudendolo a tutte le altre. Ma se anche alla collettività succede la stessa cosa! Vive di Darwin dopo di essere vissuta di Robespierre e di Napoleone eppoi di Liebig o magari di Leopardi quando su tutto il cosmo non troneggi Bismark.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Ma di Basedow vissi sol io! Mi parve ch'egli avesse portate alla luce le radici della vita la quale è fatta così: tutti gli organismi si distribuiscono su una linea, ad un capo della quale sta la malattia di Basedow che implica il generosissimo, folle consumo della forza vitale ad un ritmo precipitoso, il battito di un cuore sfrenato, e all'altro stanno gli organismi immiseriti per avarizia organica, destinati a perire di una malattia che sembrerebbe di esaurimento ed è invece di poltronaggine. Il giusto medio fra le due malattie si trova al centro e viene designato impropriamente come la salute che non è che una sosta. E fra il centro ed un'estremità — quella di Basedow — stanno tutti coloro ch'esasperano e consumano la vita in grandi desiderii, ambizioni, godimenti e anche lavoro, dall'altra quelli che non gettano sul piatto della vita che delle briciole e risparmiano preparando quegli abietti longevi che appariscono quale un peso per la società. Pare che questo peso sia anch'esso necessario. La società procede perché i Basedowiani la sospingono, e non precipita perché gli altri la trattengono. Io sono convinto che volendo costituire una società, si poteva farlo più semplicemente, ma è fatta così, col gozzo ad uno dei suoi capi e l'edema all'altro, e non c'è rimedio. In mezzo stanno coloro che hanno incipiente o gozzo o edema e su tutta la linea, in tutta l'umanità, la salute assoluta manca.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Già credo che in qualunque punto dell'universo ci si stabilisca si finisce coll'inquinarsi. Bisogna moversi. La vita ha dei veleni, ma poi anche degli altri veleni che servono di contravveleni. Solo correndo si può sottrarsi ai primi e giovarsi degli altri.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Ecco il sogno: eravamo in tre, Augusta, Ada ed io che ci eravamo affacciati ad una finestra e precisamente alla più piccola che ci fosse stata nelle nostre tre abitazioni, cioè la mia, quella di mia suocera e quella di Ada. Eravamo cioè alla finestra della cucina della casa di mia suocera che veramente si apre sopra un piccolo cortile mentre nel sogno dava proprio sul Corso. Al piccolo davanzale c'era tanto poco spazio che Ada, che stava in mezzo a noi tenendosi alle nostre braccia, aderiva proprio a me. Io la guardai e vidi che il suo occhio era ridivenuto freddo e preciso e le linee della sua faccia purissime fino alla nuca ch'io vedevo coperta dei suoi riccioli lievi, quei riccioli ch'io avevo visti tanto spesso quando Ada mi volgeva le spalle. Ad onta di tanta freddezza (tale mi pareva la sua salute) essa rimaneva aderente a me come avevo creduto lo fosse quella sera del mio fidanzamento intorno al tavolino parlante. Io, giocondamente, dissi ad Augusta (certo facendo uno sforzo per occuparmi anche di lei): «Vedi com'è risanata? Ma dov'è Basedow?» «Non vedi?» domandò Augusta che era la sola fra di noi che arrivasse a guardare sulla via. Con uno sforzo ci sporgemmo anche noi e scorgemmo una grande folla che s'avanzava minacciosa urlando. «Ma dov'è Basedow?» domandai ancora una volta. Poi lo vidi. Era lui che s'avanzava inseguito da quella folla: un vecchio pezzente coperto di un grande mantello stracciato, ma di broccato rigido, la grande testa coperta di una chioma bianca disordinata, svolazzante all'aria, gli occhi sporgenti dall'orbita che guardavano ansiosi con uno sguardo ch'io avevo notato in bestie inseguite, di paura e di minaccia. E la folla urlava: «Ammazzate l'untore!»", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Ricordai allora che una volta in Inghilterra la condanna ai lavori forzati veniva applicata appendendo il condannato al disopra di una ruota azionata a forza d'acqua, obbligando così la vittima a muovere in un certo ritmo le gambe che altrimenti gli sarebbero state sfracellate. Quando si lavora si ha sempre il senso di una costrizione di quel genere.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "La vita non è né brutta né bella, ma è originale!", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Mi pareva di aver sciolto il problema angoscioso. Non si era né buoni né cattivi come non si era tante altre cose ancora. La bontà era la luce che a sprazzi e ad istanti illuminava l'oscuro animo umano. Occorreva la fiaccola bruciante per dare la luce (nell'animo mio c'era stata e prima o poi sarebbe sicuramente anche ritornata) e l'essere pensante a quella luce poteva scegliere la direzione per moversi poi nell'oscurità. Si poteva perciò manifestarsi buoni, tanto buoni, sempre buoni, e questo era l'importante. Quando la luce sarebbe ritornata non avrebbe sorpreso e non avrebbe abbacinato. Ci avrei soffiato su per spegnerla prima, visto ch'io non ne avevo bisogno. Perché io avrei saputo conservare il proposito, cioè la direzione.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "È una delle grandi difficoltà della vita d'indovinare ciò che una donna vuole.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Nella sua grande emozione ella quasi s'appoggiava a me, come nel sogno. Ma io m'attenni alla sue parole. Mi domandava un affetto fraterno; l'impegno di amore che pensavo mi legasse a lei si trasformava così in un altro suo diritto, epperò le promisi subito di aiutare Guido, di aiutare lei, di fare quello che avrebbe voluto. Se fossi stato più sereno avrei dovuto parlare della mia insufficienza al compito ch'essa m'assegnava, ma avrei distrutta tutta l'indimenticabile emozione di quel momento. Del resto era tanto commosso che non potevo sentire la mia insufficienza. In quel momento pensavo che non esistessero affatto per nessuno delle insufficienze. Anche quella di Guido poteva essere soffiata via con alcune parole che gli dessero il necessario entusiasmo.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Sapeva abbastanza di contabilità per intendermi e invece non ci arrivava perché il desiderio gl'impediva di adattarsi all'evidenza.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "La legge naturale non dà il diritto alla felicità, ma anzi prescrive la miseria e il dolore. Quando viene esposto il commestibile, vi accorrono da tutte le parti i parassiti e, se mancano, s'affrettano di nascere. Presto la preda basta appena, e subito dopo non basta più perché la natura non fa calcoli, ma esperienze. Quando non basta più, ecco che i consumatori devono diminuire a forza di morte preceduta dal dolore e così l'equilibrio, per un istante, viene ristabilito. Perché lagnarsi? Eppure tutti si lagnano. Quelli che non hanno avuto niente della preda muoiono gridando all'ingiustizia e quelli che ne hanno avuto parte trovano che avrebbe avuto diritto ad una parte maggiore. Perché non muoiono e non vivono tacendo? È invece simpatica la gioia di chi ha saputo conquistarsi una parte esuberante del commestibile e si manifesti pure al sole in mezzo agli applausi. L'unico grido ammissibile è quello del trionfatore.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "La verità la ebbi dal dottor Paoli in cui m'imbattei sulle scale. Ne ebbi uno sconvolgimento che quasi mi fece precipitare. Guido, dacché vivevo con lui, era divenuto per me un personaggio di grande importanza. Finché era vivo lo vedevo in una data luce ch'era la luce di parte delle mie giornale. Morendo, quella luce si modificava in modo come se improvvisamente fosse passata traverso un prisma. Era proprio questo che m'abbacinava. Egli aveva sbagliato, ma io subito vidi ch'essendo morto, dei suoi errori non restava niente.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Secondo me era un imbecille quel buffone che in un cimitero coperto di epigrafi laudatorie domandò dove si seppellissero in quel paese i peccatori. I morti non sono mai stati peccatori. Guido era ormai un puro! La morte l'aveva purificato.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Quando però i miei occhi si chiusero, nell'oscurità vidi che le sue parole avevano creato un mondo nuovo come tutte le parole non vere.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Egli non studiò che la medicina e perciò ignora che cosa significhi scrivere in italiano per noi che parliamo e non sappiamo scrivere il dialetto. Una confessione in iscritto è sempre menzognera. Con ogni nostra parola toscana noi mentiamo! Se egli sapesse come raccontiamo con predilezione tutte le cose per le quali abbiamo pronta la frase e come evitiamo quelle che ci obbligherebbero di ricorrere al vocabolario! È proprio così che scegliamo dalla nostra vita gli episodi da notarsi. Si capisce come la nostra vita avrebbe tutt'altro aspetto se fosse detta nel nostro dialetto.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Credo però ch'egli sia il solo a questo mondo il quale sentendo che volevo andare, a letto con due bellissime donne si domanda: Vediamo perché costui vuole andare a letto con esse.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Nella Psicoanalisi non si ripetono mai né le stesse immagini né le stesse parole. Bisognerebbe chiamarla altrimenti. Chiamiamola l'avventura psichica. Proprio così: quando s'inizia una simili analisi è come se ci si recasse in un bosco non sapendo se c'imbatteremo in un brigante o in un amico. E non lo si sa neppure quando l'avventura è passata. In questo la psico-analisi ricorda lo spiritismo.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Fu un vero raccoglimento il mio, uno di quegl'istanti rari che l'avara vita concede, di vera grande oggettività in cui si cessa finalmente di credersi e sentirsi vittima. In mezzo a quel verde rilevato tanto deliziosamente da quegli sprazzi di sole, seppi sorridere alla mia vita ed anche alla mia malattia. La donna vi ebbe un'importanza enorme. Magari a pezzi, i suoi piedini, la sua cintura, la sua bocca, riempirono i miei giorni. E rivedendo la mia vita e anche la mia malattia le amai, le intesi! Com'era stata più bella la mia vita che non quella dei cosidetti sani, coloro che picchiavano o avrebbero voluto picchiare la loro donna ogni giorno salvo in certi momenti. Io, invece, ero stato accompagnato sempre dall'amore. Quando non avevo pensato alla mia donna, vi avevo pensato ancora per farmi perdonare che pensavo anche alle altre. Gli altri abbandonavano la donna delusi e disperando della vita. Da me la vita non fu mai privata del desiderio e l'illusione rinacque subito intera dopo ogni naufragio, nel sogno di membra, di voci, di atteggiamenti più perfetti.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Il sole non illuminò me! Quando si è vecchi si resta all'ombra anche avendo dello spirito.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Non è per il confronto ch'io mi senta sano. Io sono sano, assolutamente. Da lungo tempo io sapevo che la mia salute non poteva essere altro che la mia convinzione e ch'era una sciocchezza degna di un sognatore ipnagogico di volerla curare anziché persuadere. Io soffro bensì di certi dolori, ma mancano d'importanza nella mia grande salute. Posso mettere un impiastro qui o là, ma il resto ha da moversi e battersi e mai indugiarsi nell'immobilità come gl'incancreniti. Dolore e amore, poi, la vita insomma, non può essere considerata quale una malattia perché duole.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Ammetto che per avere la persuasione della salute il mio destino dovette mutare e scaldare il mio organismo con la lotta e sopratutto col trionfo. Fu il mio commercio che mi guarì e voglio che il dottor S. lo sappia.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Naturalmente io non sono un ingenuo e scuso il dottore di vedere nella vita stessa una manifestazione di malattia. La vita somiglia un poco alla malattia come procede per crisi e lisi ed ha i giornalieri miglioramenti e peggioramenti. A differenza delle altre malattie la vita è sempre mortale. Non sopporta cure. Sarebbe come voler turare i buchi che abbiamo nel corpo credendoli delle ferite. Morremmo strangolati non appena curati.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "La vita attuale è inquinata alle radici. L'uomo s'è messo al posto degli alberi e delle bestie ed ha inquinata l'aria, ha impedito il libero spazio. Può avvenire di peggio. Il triste e attivo animale potrebbe scoprire e mettere al proprio servizio delle altre forze. V'è una minaccia di questo genere in aria. Ne seguirà una grande ricchezza... nel numero degli uomini. Ogni metro quadrato sarà occupato da un uomo. Chi ci guarirà della mancanza di aria e di spazio? Solamente al pensarci soffoco!", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Qualunque sforzo di darci la salute è vano. Questa non può appartenere che alla bestia che conosce un solo progresso, quello del proprio organismo. Allorché la rondinella comprese che per essa non c'era altra possibile vita fuori dell'emigrazione, essa ingrossò il muscolo che muove le sue ali e che divenne la parte più considerevole del suo organismo. La talpa s'interrò e tutto il suo corpo si conformò al suo bisogno. Il cavallo s'ingrandì e trasformò il suo piede. Di alcuni animali non sappiamo il progresso, ma ci sarà stato e non avrà mai leso la loro salute.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Ma l'occhialuto uomo, invece, inventa gli ordigni fuori del suo corpo e se c'è stata salute e nobiltà in chi li inventò, quasi sempre manca in chi li usa. Gli ordigni si comperano, si vendono e si rubano e l'uomo diventa sempre più furbo e più debole. Anzi si capisce che la sua furbizia cresce in proporzione della sua debolezza. I primi suoi ordigni parevano prolungazioni del suo braccio e non potevano essere efficaci che per la forza dello stesso, ma, oramai, l'ordigno non ha più alcuna relazione con l'arto. Ed è l'ordigno che crea la malattia con l'abbandono della legge che fu su tutta la terra la creatrice. La legge del più forte sparì e perdemmo la selezione salutare. Altro che psico-analisi ci vorrebbe: Sotto la legge del possessore del maggior numero di ordigni prospereranno malattia e ammalati.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Forse traverso una catastrofe inaudita prodotta dagli ordigni ritorneremo alla salute. Quando i gas velenosi non basteranno più, un uomo fatto come tutti gli altri, nel segreto di una stanza di questo mondo, inventerà un esplosivo incomparabile, in confronto al quale gli esplosivi attualmente esistenti saranno considerati quali innocui giocattoli. Ed un altro uomo fatto anche lui come tutti gli altri, ma degli altri un po' più ammalato, ruberà tale esplosivo e s'arrampicherà al centro della terra per porlo nel punto ove il suo effetto potrà essere il massimo. Ci sarà un'esplosione enorme che nessuno udrà e la terra ritornata alla forma di nebulosa errerà nei cieli priva di parassiti e di malattie.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Fuori della penna non c'è salvezza.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "L'immaginazione è una vera avventura. Guàrdati dall'annotarla troppo presto perché la rendi quadrata e poco adattabile al tuo quadro. Deve restare fluida come la vita stessa che è e diviene.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "La descrizione della vita, una grande parte della quale, quella di cui tutti sanno e non parlano, è eliminata, si fa tanto più intensa della vita stessa.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "La morte è l'ammirevole liquidazione della vita. Quando il filosofo amaro ghigna che il suicidio non è altro che un palliativo, come tutti coloro che per vedere meglio s'innalzarono di troppo. Vedono il paese, non l'albero, non la casetta. Il destino del singolo è piccolo anche dinanzi alla morte. Per la morte il piccolo singolo rientra privo di ogni responsabilità nella vita generale e vi si annulla. Come non riconoscere che la morte cancella ogni dolore per le nostre sventure, per le nostre debolezze e per i nostri errori? La debolezza è memoria.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Il Brentani parlava spesso della sua esperienza. Ciò ch'egli credeva di poter chiamare così era qualche cosa ch'egli aveva succhiato dai libri, una grande diffidenza e un grande disprezzo dei propri simili.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Le donne oneste erano quelle che sapevano trovare l'acquirente al prezzo più alto, erano quelle che non consentivano all'amore che quando ci trovavano il loro tornaconto. Dicendo queste parole egli si sentì l'uomo immorale superiore che vede e vuole le cose come sono.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Ci eravamo trovati tanto bene insieme! Io, la persona più intelligente della città e lui la quinta, perché dopo di me vi sono tre posti vuoti e subito al prossimo c'è lui.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Quando una ragazza permette ad un giovine di dirle d'amarla, ella è già sua e non più libera.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Il possesso non dava la verità, ma esso stesso, non abbellito da sogni e neppure da parole, era la verità propria e pura e bestiale.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "L'immagine della morte è bastevole ad occupare tutto un intelletto. Gli sforzi per trattenerla o per respingerla sono titanici, perché ogni nostra fibra terrorizzata la ricorda dopo averla sentita vicina, ogni nostra molecola la respinge nell'atto stesso di conservare e produrre la vita. Il pensiero di lei è come una qualità, una malattia dell'organismo. La volontà non lo chiama né lo respinge.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "È strano di trovare ai nostri tempi una persona ingenua. Viene voglia di guarirla da una malattia tanto adorabile.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Strano — pensò, — sembrerebbe che metà dell'umanità esista per vivere e l'altra per essere vissuta.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Gli uomini, specialmente coloro i quali hanno il vero entusiasmo per lo studio, sono più idonei ad insegnare che non le donne le quali amano le cose piccole e si perdono in particolari inutili e perciò dannosi alla comprensione del tutto.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Macario cadeva spesso in contraddizioni, ma mai nel medesimo giorno.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Quanto poco cervello occorre per pigliare pesce! Il corpo è piccolo. Che cosa sarà la testa e che cosa sarà poi il cervello? Quantità da negligersi! Quello ch'è la sventura del pesce che finisce in bocca del gabbiano sono quelle ali, quegli occhi, e lo stomaco, l'appetito formidabile per soddisfare il quale non è nulla quella caduta così dall'alto. Ma il cervello! Che cosa ci ha da fare il cervello col pigliar pesci? E lei che studia, che passa ore intere a tavolino a nutrire un essere inutile! Chi non ha le ali necessarie quando nasce non gli crescono mai più. Chi non sa per natura piombare a tempo debito sulla preda non lo imparerà giammai e inutilmente starà a guardare come fanno gli altri, non li saprà imitare. Si muore precisamente nello stato in cui si nasce, le mani organi per afferrare o anche inabili a tenere.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Gesù non si deride, i suoi vicari sì.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Certi giovani per amore all'accuratezza diventano pedanti prima del tempo, preferiscono la lima alla penna e finiscono col non far niente. [...] Per adoperare la lima occorre, oltre che molto ingegno, molto senno critico. Quando si fa si è artisti, ma quando si lima bisogna essere artisti e scienziati.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "È difficile! — cominciai Alfonso — ma qualche cosa credo di poterne dire. Raccontò che prima di tutto era una malattia organica perché soffrivano i polmoni per la differenza dell'aria, lo stomaco per la differenza dei cibi, i piedi per la differenza del selciato. Quello che però rinunziava a descrivere era l'intensità del desiderio di rivedere i luoghi che si erano abbandonati, un muro nero, una via tortuosa col canale nel mezzo, infine una stanza incomoda mal riparata dalle intemperie; e non si poteva descrivere l'aborrimento per il palazzo in cui abitava, alludeva a quello della banca, la via grande, spaziosa, e persino il mare: — In quanto alle persone poi... è la stessa cosa.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "La tribù s'era fermata. Aveva trovato in mezzo al deserto un vasto paese ricco d'acqua, di prati e d'alberi, e, involontariamente, senza che nessuno lo proponesse, invece di farvi una delle solite soste fugaci, aveva messo radice in quel paradiso, era stata avvinghiata dalla terra e non aveva più saputo staccarsene.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Molti quando si trovano fra' dieci e i quindici anni sognano una carriera grande, persino quella di Napoleone. Non era quindi strano che a 12 anni Vincenzo Albagi pensò che se Napoleone a 30 anni era stato proclamato imperatore egli avrebbe potuto esserlo qualche anno prima.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Amelia era un'ottima fanciulla educata ai migliori principî e quando venne il tempo di maritarsi, il padre suo, ch'era un onesto negoziante, le disse un giorno con aria soddisfatta che un milionario del paese aveva domandato la sua mano.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "I una valle chiusa da colline boschive, sorridente nei colori della primavera, s'ergevano una accanto all'altra due grandi case disadorne, pietra e calce. Parevano fatte dalla stessa mano, e anche i giardini chiusi da siepi, posti dinanzi a ciascuna di esse, erano della stessa dimensione e forma. Chi vi abitava non aveva però lo stesso destino.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Avevo circa 25 anni quando nelle riunioni sociali di Trieste fece la sua comparsa un ricco signore abruzzese certo Cima. Io non sapevo perché egli avesse prescelto Trieste a suo soggiorno. Non vi era condotto né da parentela né da affari. Glielo domandai: Trieste era una bellissima città per chi v'era nato ma a questo mondo c'era di meglio avendo la libertà di scelta.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Nelle mie lunghe peregrinazioni a piedi traverso le campagne del Friuli io ho l'abitudine d'accompagnarmi a chi incontro e di provocare le confidenze. Io vengo detto chiacchierone ma pur sembra che la mia parola non sia tale da impedire l'altrui perché da ogni mia gita riporto a casa comunicazioni importanti che illuminano di vivida luce il paesaggio per cui passo.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Quando si domandavano a Marianno particolari della sua gioventù egli ben poco ne sapeva dire. Del suo soggiorno all'Ospizio egli poco ricordava. La mente dovette aprirglisi il giorno in cui lasciò l'Ospizio. Alessandro il suo futuro padrone vestito a festa era venuto a prenderlo ed egli lo ricordava come prometteva di aver cura di lui con quel suo sorriso bonario e affettuoso.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Era una calda giornata di Luglio. La mattina tanto di buon'ora era già soffocante. Il signor Perini fece un giro nel deposito prima che alcun operaio vi fosse entrato e quando ne uscì s'imbatté in Giuseppe Cimutti che, primo fra gli operai, vi entrava.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "La luce veniva lenta a destare i colori della palude, del canale, della spiaggia verde dell'isola. L'enorme piano s'era illuminato gradatamente tutto nello stesso tempo. Il sole non si vedeva ancora ma la luce che riverberava dal cielo si diffondeva senz'ostacoli dappertutto nello stesso tempo.", Author = "Italo Svevo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Svevo", Text = "Un paese lontano dall'Italia e da Trieste. Roberto ricordava meglio che il paese stesso, la crisi c", Author = "Italo Svevo" },
        };
    }
}